 const dead=casualtyCount(text,'dead'),injured=casualtyCount(text,'injured'),evacuated=casualtyCount(text,'evacuated'),mass=dead>=5||injured>=20||/cok sayida (?:olu|kisi hayatini|kisi yaralandi)|cok sayida can kaybi/.test(text),deaths=(dead>=1||/hayatini kaybetti|yasamini yitirdi|\bolu\b/.test(text))&&!/can kaybi (?:yok|olmadi|yasanmadi)|olen yok/.test(text);
